import java.io.*;
import java.util.*;

public class Main {
    static final int[][] vis = new int[110][110];
    static final int[][] directions = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    static class Node implements Comparable<Node> {
        int x, y, step;

        Node(int x, int y, int step) {
            this.x = x;
            this.y = y;
            this.step = step;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.step, other.step);
        }
    }

    static int bfs(int l, int u, int xi, int yi) {
        PriorityQueue<Node> queue = new PriorityQueue<>();
        queue.offer(new Node(l, u, 0));
        vis[l][u] = 1;

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            if (current.x == xi && current.y == yi) {
                return current.step;
            }

            for (int[] direction : directions) {
                int nx = current.x + direction[0];
                int ny = current.y + direction[1];

                if (nx < 0 || ny < 0 || nx >= 110 || ny >= 110) {
                    continue;
                }
                if (vis[nx][ny] != 0) {
                    continue;
                }

                vis[nx][ny] = 1;
                queue.offer(new Node(nx, ny, current.step + 1));
            }
        }

        return -1;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(
            new InputStreamReader(System.in)
        );
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        String s = tokenizer.nextToken();

        int len = s.length();
        int x = 0, y = 0, xx = 0, yy = 0;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            if (c == 'L') y--;
            if (c == 'R') y++;
            if (c == 'U') x--;
            if (c == 'D') x++;

            xx = Math.min(xx, x);
            yy = Math.min(yy, y);
        }

        xx = -xx;
        yy = -yy;

        for (int i = 0; i < 110; i++) {
            Arrays.fill(vis[i], 1);
        }

        x = xx;
        y = yy;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            if (c == 'L') y--;
            if (c == 'R') y++;
            if (c == 'U') x--;
            if (c == 'D') x++;

            vis[x][y] = 0;
        }

        int ans = bfs(xx, yy, x, y);
        System.out.println(ans == len ? "OK" : "BUG");
    }
}

